CREATE DATABASE IF NOT EXISTS `well`;
USE `well`;

DROP TABLE IF EXISTS `well_daily`;

CREATE TABLE `well_daily` (
    `date` DATE NOT NULL PRIMARY KEY,
    `open` DECIMAL(20,10) NULL,
    `high` DECIMAL(20,10) NULL,
    `low` DECIMAL(20,10) NULL,
    `close` DECIMAL(20,10) NULL,
    `adjClose` DECIMAL(20,10) NULL,
    `volume` BIGINT NULL
);

























